def is_palindrome(s):
    c = ''.join(ch.lower() for ch in s if ch.isalnum())
    return c == c[::-1]

def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(str(i))
    return result

def second_largest(nums):
    uniq = set(nums)
    if len(uniq) < 2:
        return None
    uniq.remove(max(uniq))
    return max(uniq)

def count_words(text):
    counts = {}
    cur = []
    def flush():
        if cur:
            w = ''.join(cur).lower()
            counts[w] = counts.get(w, 0) + 1
            cur.clear()
    for ch in text:
        o = ord(ch)
        if (65 <= o <= 90) or (97 <= o <= 122):
            cur.append(ch)
        else:
            flush()
    flush()
    return counts

def merge_intervals(intervals):
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [list(intervals[0])]
    for s, e in intervals[1:]:
        if s <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    return merged

def is_valid_parentheses(s):
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}
    for c in s:
        if c in mapping.values():
            stack.append(c)
        elif c in mapping:
            if not stack or stack.pop() != mapping[c]:
                return False
    return not stack
